import csv, json
from pathlib import Path

q_csv = Path('csv/qualifying.csv')
drv_json = Path('json/drivers.json')

# load drivers
with drv_json.open(encoding='utf-8') as f:
    data = json.load(f)
if isinstance(data, dict) and 'records' in data:
    drivers_list = data['records']
elif isinstance(data, list):
    drivers_list = data
else:
    raise SystemExit('Unexpected drivers.json structure')

# map by driverId (as string)
driver_by_id = {str(d.get('driverId')): d for d in drivers_list}

best = None
with q_csv.open(encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        if r['raceId'] != '19':
            continue
        q2 = r['q2'].strip()
        if q2 == '':
            continue
        try:
            if ':' in q2:
                m, s = q2.split(':')
                seconds = int(m) * 60 + float(s)
            else:
                seconds = float(q2)
        except Exception:
            continue
        if best is None or seconds < best[0]:
            best = (seconds, r)

if best is None:
    print(json.dumps({'error':'no q2 times for raceId 19'}))
else:
    seconds, row = best
    driver_id = row['driverId']
    driver = driver_by_id.get(str(driver_id))
    surname = driver.get('surname') if driver else None
    print(json.dumps({'driverId': driver_id, 'surname': surname, 'q2': row['q2'], 'seconds': seconds}))

